            Lb,Rb=cf(sub); bvm.append((deconv(Lb,Rb)*Aw).sum())
        print('   ',nm,'readout %.3f (approx sd %.3f)'%((deconv(Lm,Rm)*Aw).sum(), np.std(bvm)))
    return ep, L_, R_
